from pathlib import Path
p=Path('/mnt/data/v12work/index.html')
s=p.read_text()
# CSS
s=s.replace('header{background:#fff;padding:0;box-shadow:0 2px 12px #0001}.fixedbar{background:#fff;padding:12px 14px 10px}', 'header{background:#fff;padding:0;box-shadow:0 2px 12px #0001}.fixedbar{background:#fff;padding:12px 14px 10px}.appbar{display:flex;align-items:center;justify-content:space-between;gap:10px}.appTitle{font-size:20px;font-weight:800}.menuBtn{width:42px;height:42px;padding:0;border-radius:10px;background:#fff;color:#222;border:1px solid #ddd;font-size:25px;line-height:1}.menuBtn span{display:block;line-height:1}')
s=s.replace('button{font:inherit;border:0;border-radius:11px;padding:11px;background:#222;color:#fff;font-weight:700}', 'button{font:inherit;border:0;border-radius:10px;padding:9px 11px;background:#222;color:#fff;font-weight:700}.compactBtn{padding:8px 10px;font-size:14px}')
s=s.replace('.profileRow{display:flex;gap:8px;align-items:center;padding:12px 0;border-bottom:1px solid #eee}', '.profileRow{display:flex;gap:8px;align-items:center;padding:12px 0;border-bottom:1px solid #eee}.menuSheet{position:fixed;inset:0;background:#0007;z-index:30}.menuPanel{position:absolute;top:0;right:0;width:min(390px,88vw);height:100%;background:#fff;box-shadow:-4px 0 20px #0002;overflow:auto}.menuHead{display:flex;align-items:center;justify-content:space-between;padding:18px 16px;border-bottom:1px solid #eee}.menuHead h2{margin:0;font-size:22px}.menuSection{padding:16px;border-bottom:1px solid #eee}.menuLabel{font-size:13px;color:#777;font-weight:700;margin-bottom:8px}.menuItem{display:flex;align-items:center;gap:10px;width:100%;text-align:left;background:#fff;color:#252329;padding:12px 0;border-radius:0;font-weight:600}.menuItem+.menuItem{border-top:1px solid #f1f1f1}.menuIcon{width:24px;text-align:center;font-size:19px}.menuProfile{font-size:17px;font-weight:800;line-height:1.35}.menuSub{font-size:12px;color:#888;margin-top:3px}')
# Header by positions
hs=s.index('<header>'); he=s.index('</header>',hs)+len('</header>')
header='''<header>\n<div class="fixedbar">\n  <div class="appbar"><div class="appTitle">Card Collector</div><button class="menuBtn" id="menuBtn" aria-label="メニュー"><span>☰</span></button></div>\n  <div class="stats"><span id="count">0 / 0</span><span id="pct">0%</span></div><input id="q" placeholder="カード番号・カード名・レアリティを検索">\n</div>\n<div class="tools">\n<div class="controls"><select id="status"><option value="">すべて</option><option value="no">未所持</option><option value="yes">所持</option><option value="want">欲しい</option></select><select id="rarity"><option value="">全レアリティ</option></select></div>\n<div class="top"><button class="collectionMode compactBtn" data-mode="trade">交換用モード</button><button id="collectionBtn" class="collectionBtn compactBtn">画像に保存</button></div>\n</div>\n</header>'''
s=s[:hs]+header+s[he:]
# Replace old profile sheet through collection modal
ps=s.index('<div class="sheet hidden" id="profilesSheet">') if '<div class="sheet hidden" id="profilesSheet">' in s else -1
cm=s.index('<div class="modal hidden" id="collectionModal">')
if ps>=0:
    menu='''<div class="menuSheet hidden" id="menuSheet">\n  <div class="menuPanel">\n    <div class="menuHead"><h2>メニュー</h2><button class="close" id="menuClose">×</button></div>\n    <div class="menuSection"><div class="menuLabel">現在のプロファイル</div><div class="menuProfile" id="menuCurrentProfile">—</div></div>\n    <div class="menuSection" id="profileMenuList"></div>\n    <div class="menuSection">\n      <button class="menuItem" id="menuImport"><span class="menuIcon">＋</span><span>プロファイルをインポート</span></button>\n      <button class="menuItem" id="menuExport"><span class="menuIcon">↓</span><span>エクスポート</span></button>\n    </div>\n  </div>\n</div>\n\n'''
    s=s[:ps]+menu+s[cm:]
# Remove emojis on collection save and compact
s=s.replace('<button id="collectionSave" style="width:100%;margin-top:10px">画像に保存</button>', '<button id="collectionSave" class="compactBtn" style="width:100%;margin-top:10px">画像を保存</button>')
# renderProfiles function
rs=s.index('function renderProfiles(){'); re=s.index('function selectP',rs)
render='''function renderProfiles(){renderMenu()}\nfunction renderMenu(){\n const p=active();\n $("menuCurrentProfile").innerHTML=p?esc(p.name):'プロファイルがありません';\n const list=profiles.length?profiles.map(x=>`<div class="profileRow"><div class="name">${esc(x.name)}<div class="small">${x.cards.length}枚</div></div>${x.id===activeId?'<span class="small">使用中</span>':''}<button class="light compactBtn" onclick="selectP('${esc(x.id)}')">開く</button><button class="light compactBtn" aria-label="削除" onclick="removeP('${esc(x.id)}')">削除</button></div>`).join(''):'<div class="msg">まだプロファイルがありません</div>';\n $("profileMenuList").innerHTML=list;\n}\n'''
s=s[:rs]+render+s[re:]
# trade funcs
old='''function getTradeCount(c,p){\n  const key="ownedCount_"+p.id;\n  try{\n    const obj=JSON.parse(localStorage.getItem(key)||"{}");\n    return Math.max(0,parseInt(obj[c.id]||0,10)||0);\n  }catch(e){return 0}\n}\nfunction setTradeCount(c,p,n){\n  const key="ownedCount_"+p.id;\n  let obj={};\n  try{obj=JSON.parse(localStorage.getItem(key)||"{}")||{}}catch(e){}\n  obj[c.id]=Math.max(0,n);\n  localStorage.setItem(key,JSON.stringify(obj));\n}'''
new='''function getTradeCount(c,p){\n  const key="ownedCount_"+p.id;\n  try{\n    const obj=JSON.parse(localStorage.getItem(key)||"{}");\n    if(Object.prototype.hasOwnProperty.call(obj,c.id)) return Math.max(0,parseInt(obj[c.id],10)||0);\n  }catch(e){}\n  return getSet("owned",p.id).has(c.id)?1:0;\n}\nfunction setTradeCount(c,p,n){\n  const key="ownedCount_"+p.id;\n  let obj={};\n  try{obj=JSON.parse(localStorage.getItem(key)||"{}")||{}}catch(e){}\n  obj[c.id]=Math.max(0,n);\n  localStorage.setItem(key,JSON.stringify(obj));\n  const owned=getSet("owned",p.id);\n  if(n>0) owned.add(c.id); else owned.delete(c.id);\n  putSet("owned",p.id,owned);\n}'''
if old not in s: raise SystemExit('trade funcs not found')
s=s.replace(old,new)
# compact trade card buttons
s=s.replace('''<div style="display:flex;align-items:center;justify-content:center;gap:10px;padding:4px 4px 5px;border-top:1px solid #eee;">\n          <button class="tradeMinus" style="width:28px;height:28px;font-size:20px;line-height:1;padding:0;">−</button>\n          <strong class="tradeCount" style="min-width:20px;text-align:center;font-size:16px;">${count}</strong>\n          <button class="tradePlus" style="width:28px;height:28px;font-size:20px;line-height:1;padding:0;">＋</button>\n        </div>''','''<div style="display:flex;align-items:center;justify-content:center;gap:6px;padding:3px 2px 4px;border-top:1px solid #eee;">\n          <button class="tradeMinus compactBtn" aria-label="1枚減らす" style="width:26px;height:26px;font-size:17px;line-height:1;padding:0;">−</button>\n          <strong class="tradeCount" style="min-width:18px;text-align:center;font-size:14px;">${count}</strong>\n          <button class="tradePlus compactBtn" aria-label="1枚増やす" style="width:26px;height:26px;font-size:17px;line-height:1;padding:0;">＋</button>\n        </div>''')
# collection image function
cs=s.index('async function makeCollectionImage(mode=collectionMode){'); ce=s.index('function saveCollectionImage(){',cs)
func='''async function loadCanvasImage(url){\n  const sources=[url,proxyImageUrl(url)];\n  for(const src of sources){\n    try{const img=new Image();img.crossOrigin='anonymous';img.src=src;await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;setTimeout(()=>rej(new Error('timeout')),8000)});if(img.naturalWidth&&img.naturalHeight)return img;}catch(e){}\n  }\n  return null;\n}\nasync function makeCollectionImage(mode=collectionMode){\n collectionMode=mode;\n let p=active();if(!p){alert('プロファイルがありません。');return}\n const filtered=currentFilteredCards(p),selected=collectionCards(p,mode);\n const noSelection=selected.length===0&&!$('status').value,effectiveSelected=noSelection?filtered:selected;\n const showUnselected=$('collectionShowUnselected').checked,groupByCoordinate=$('collectionGroupByCoordinate').checked;\n const cards=showUnselected?filtered:effectiveSelected,selectedIds=new Set(effectiveSelected.map(c=>c.id));\n if(!cards.length){alert((mode==='owned'?'所持':mode==='wanted'?'欲しい':'未所持')+'カードがありません。');return}\n $('collectionModal').classList.remove('hidden');$('collectionInfo').textContent='画像を作成しています…';\n document.querySelectorAll('.collectionMode').forEach(b=>{if(b.dataset.mode!=='trade'){b.style.background=b.dataset.mode===mode?'#222':'#eee';b.style.color=b.dataset.mode===mode?'#fff':'#222'}});\n const groups=groupByCoordinate?groupCardsByCoordinate(cards):[{title:'',cards}],maxCols=groupByCoordinate?Math.max(...groups.map(g=>g.cards.length),1):Math.max(cards.length,1);\n const cols=groupByCoordinate?Math.min(maxCols,7):(cards.length<=12?3:cards.length<=30?4:cards.length<=60?5:6),maxCanvasW=1400,pad=24,gap=12;\n const cellW=Math.max(120,Math.floor((maxCanvasW-pad*2-gap*(cols-1))/cols)),imgW=Math.max(95,cellW-18),imgH=Math.round(imgW*1.375),labelH=52,titleH=78,groupTitleH=28,rowGap=12;\n const rowHeights=groups.map(g=>(groupByCoordinate?groupTitleH:0)+imgH+labelH+rowGap),canvas=$('collectionCanvas');\n canvas.width=cols*cellW+pad*2+gap*(cols-1);canvas.height=titleH+rowHeights.reduce((a,b)=>a+b,0)+pad;\n const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);\n ctx.fillStyle='#222';ctx.font='bold 24px -apple-system,BlinkMacSystemFont,sans-serif';ctx.fillText(p.name,pad,30);ctx.font='16px -apple-system,BlinkMacSystemFont,sans-serif';ctx.fillText(`${noSelection?'全表示':(mode==='owned'?'所持':mode==='wanted'?'欲しい':'未所持')} ${effectiveSelected.length}枚${showUnselected?'（未選択カードは半透明）':''}`,pad,56);\n const loaded=await Promise.all(cards.map(async c=>({c,img:await loadCanvasImage(c.image)}))),loadedMap=new Map(loaded.map(x=>[x.c.id,x.img]));\n let yCursor=titleH;\n for(const g of groups){\n   if(groupByCoordinate&&g.title){ctx.fillStyle='#222';ctx.font='bold 16px sans-serif';ctx.fillText(g.title,pad,yCursor+18);yCursor+=groupTitleH;}\n   g.cards.forEach((c,i)=>{const x=pad+i*(cellW+gap)+9,y=yCursor+4,img=loadedMap.get(c.id);ctx.save();if(showUnselected&&!selectedIds.has(c.id))ctx.globalAlpha=.28;if(img){const ratio=Math.min(imgW/img.naturalWidth,imgH/img.naturalHeight),w=img.naturalWidth*ratio,h=img.naturalHeight*ratio;ctx.drawImage(img,x+(imgW-w)/2,y+(imgH-h)/2,w,h)}else{ctx.fillStyle='#eee';ctx.fillRect(x,y,imgW,imgH);ctx.fillStyle='#777';ctx.font='14px sans-serif';ctx.fillText('画像なし',x+10,y+imgH/2)}ctx.fillStyle='#222';ctx.font='bold 14px sans-serif';ctx.fillText(c.number||'',x,y+imgH+18);if(c.rarity){ctx.font='13px sans-serif';ctx.fillText(c.rarity,x+Math.max(70,imgW-32),y+imgH+18)}if(c.name){ctx.font='12px sans-serif';ctx.fillText(String(c.name).slice(0,16),x,y+imgH+38)}ctx.restore();});\n   yCursor+=imgH+labelH+rowGap;\n }\n $('collectionInfo').textContent=`${cards.length}枚をまとめました。現在の絞り込みを反映しています。`;\n}\n'''
s=s[:cs]+func+s[ce:]
# handlers from marker to end before owned handler
hs=s.index('document.querySelectorAll(".collectionMode")')
he=s.index('$("owned").onclick=',hs)
handlers='''document.querySelectorAll(".collectionMode").forEach(b=>b.onclick=()=>b.dataset.mode==="trade"?openTradeMode():makeCollectionImage(b.dataset.mode));\n$("collectionBtn").onclick=()=>makeCollectionImage(collectionMode);\n$("collectionShowUnselected").onchange=()=>{if(!$("collectionModal").classList.contains("hidden"))makeCollectionImage(collectionMode)};\n$("collectionGroupByCoordinate").onchange=()=>{if(!$("collectionModal").classList.contains("hidden"))makeCollectionImage(collectionMode)};\n$("collectionSave").onclick=saveCollectionImage;$('collectionClose').onclick=()=>$("collectionModal").classList.add("hidden");\n$("menuImport").onclick=()=>{$("file").click();$("menuSheet").classList.add("hidden")};$("menuExport").onclick=exportProfile;\n$("file").onchange=e=>{if(e.target.files[0])importFile(e.target.files[0]);e.target.value=""};\n$("menuBtn").onclick=()=>{renderMenu();$("menuSheet").classList.remove("hidden")};$("menuClose").onclick=()=>$("menuSheet").classList.add("hidden");\n$("modalClose").onclick=()=>$("modal").classList.add("hidden");\n'''
s=s[:hs]+handlers+s[he:]
p.write_text(s)
